@startuml

class Well {
  + code : string
  + pollutionRate() : double
}

abstract class Company {
  + taxCode : string
  + numberOfEmployees : int
}

interface OilCompany extends Company {}

class OnshoreWell {
  + surfaceExtension : double
}

class OffshoreWell {
  + yearOfInstallation : int
  + geographicalArea : GeographicalArea
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

OilCompany "0..*" -- "*" Well : extractsCrudeFrom
OnshoreWell <|-- Well
OffshoreWell <|-- Well

@enduml

